package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math3.analysis.FunctionEvaluationException;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.ConvergenceException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Unit tests for UnivariateRealSolverUtils.bracket
 */
public class UnivariateRealSolverUtils_bracket_TriageGen1Test {

    @Test
    public void testBracket_NullFunction() {
        try {
            UnivariateRealSolverUtils.bracket(null, 0, -10, 10, 10);
            fail("Expected IllegalArgumentException for null function");
        } catch (IllegalArgumentException e) {
            assertEquals("function is null", e.getMessage());
        } catch (Exception e) {
            fail("Expected IllegalArgumentException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testBracket_InvalidMaximumIterations() {
        UnivariateRealFunction f = x -> x;
        try {
            UnivariateRealSolverUtils.bracket(f, 0, -10, 10, 0);
            fail("Expected IllegalArgumentException for maximumIterations <= 0");
        } catch (IllegalArgumentException e) {
            // Message contains the value in a formatted way based on implementation
            // We check if it contains the expected substring
            assert(e.getMessage().contains("bad value for maximum iterations number"));
        } catch (Exception e) {
            fail("Expected IllegalArgumentException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testBracket_InvalidBounds() {
        UnivariateRealFunction f = x -> x;
        // Case 1: initial < lowerBound
        try {
            UnivariateRealSolverUtils.bracket(f, -5, 0, 10, 10);
            fail("Expected IllegalArgumentException: initial < lowerBound");
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("invalid bracketing parameters"));
        }

        // Case 2: initial > upperBound
        try {
            UnivariateRealSolverUtils.bracket(f, 15, 0, 10, 10);
            fail("Expected IllegalArgumentException: initial > upperBound");
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("invalid bracketing parameters"));
        }

        // Case 3: lowerBound >= upperBound
        try {
            UnivariateRealSolverUtils.bracket(f, 5, 10, 5, 10);
            fail("Expected IllegalArgumentException: lowerBound >= upperBound");
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("invalid bracketing parameters"));
        }
    }

    @Test
    public void testBracket_SuccessfulBracketing() throws Exception {
        // f(x) = x^2 - 4. Roots at -2 and 2.
        // Start at 0. Bounds [-5, 5].
        // Iteration 1: a = max(0-1, -5) = -1, b = min(0+1, 5) = 1. f(-1)= -3, f(1)= -3. fa*fb = 9 (>0)
        // Iteration 2: a = max(-1-1, -5) = -2, b = min(1+1, 5) = 2. f(-2)= 0, f(2)= 0. fa*fb = 0 (<=0)
        // Loop terminates.
        UnivariateRealFunction f = x -> x * x - 4.0;
        double[] result = UnivariateRealSolverUtils.bracket(f, 0, -5, 5, 10);

        assertEquals(-2.0, result[0], 1e-10);
        assertEquals(2.0, result[1], 1e-10);
    }

    @Test
    public void testBracket_ConvergenceFailure_MaxIterations() {
        // Function that never crosses zero within bounds
        // f(x) = 1 (always positive)
        UnivariateRealFunction f = x -> 1.0;
        int maxIter = 3;
        try {
            UnivariateRealSolverUtils.bracket(f, 0, -5, 5, maxIter);
            fail("Expected ConvergenceException due to max iterations");
        } catch (ConvergenceException e) {
            // Success
        } catch (Exception e) {
            fail("Expected ConvergenceException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testBracket_ConvergenceFailure_NoRootFound() throws FunctionEvaluationException {
        // Function that stays positive but hits boundaries
        // f(x) = 1.0. Loop terminates when (a <= lowerBound && b >= upperBound)
        // or when numIterations >= maxIterations.
        // If it exits via bounds and fa*fb is still > 0, it throws ConvergenceException.
        UnivariateRealFunction f = x -> 1.0;
        try {
            UnivariateRealSolverUtils.bracket(f, 0, -2, 2, 10);
            fail("Expected ConvergenceException because no sign change was found");
        } catch (ConvergenceException e) {
            // Success
        } catch (Exception e) {
            fail("Expected ConvergenceException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testBracket_FunctionEvaluationException() {
        // Simulate a function that throws an exception
        UnivariateRealFunction f = x -> {
            if (x == 1.0) {
                throw new FunctionEvaluationException(new RuntimeException("Evaluation error"), 1.0);
            }
            return x;
        };

        try {
            // Force iteration to hit x=1.0
            // initial=0, a will go 0 -> -1, b will go 0 -> 1
            UnivariateRealSolverUtils.bracket(f, 0, -5, 5, 10);
            fail("Expected FunctionEvaluationException");
        } catch (FunctionEvaluationException e) {
            // Success
        } catch (Exception e) {
            fail("Expected FunctionEvaluationException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testBracket_BoundarySignChange() throws Exception {
        // Test where the root is exactly at the boundary
        // f(x) = x. Root at 0.
        // initial = 0.5, lower = -5, upper = 5
        // a = max(0.5-1, -5) = -0.5, b = min(0.5+1, 5) = 1.5
        // f(-0.5) = -0.5, f(1.5) = 1.5. Product < 0.
        UnivariateRealFunction f = x -> x;
        double[] result = UnivariateRealSolverUtils.bracket(f, 0.5, -5, 5, 10);

        assertEquals(-0.5, result[0], 1e-10);
        assertEquals(1.5, result[1], 1e-10);
    }
}
